"use client";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { Maximize2, Minimize2 } from "lucide-react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";

const ExpansionContext = createContext<{
  expanded: boolean;
  expand: () => void;
} | null>(null);

export function ContactsTableExpandButton() {
  const context = useContext(ExpansionContext);
  const tooltipId = useId();
  if (!context || context.expanded) return null;
  return (
    <span className="group relative inline-flex shrink-0">
      <Button
        type="button"
        size="icon"
        variant="ghost"
        className="rounded-xl border border-[var(--contacts-strong)] hover:border-2 hover:border-[var(--contacts-purple)]"
        aria-label="Expand contacts table"
        aria-describedby={tooltipId}
        aria-haspopup="dialog"
        onClick={context.expand}
      >
        <Maximize2 aria-hidden="true" />
      </Button>
      <span
        id={tooltipId}
        role="tooltip"
        className="pointer-events-none absolute top-full right-0 z-10 mt-1 hidden whitespace-nowrap rounded-md bg-foreground px-2 py-1 font-sans text-xs font-normal normal-case tracking-normal text-background shadow-sm group-hover:block group-focus-within:block"
      >
        Expand table
      </span>
    </span>
  );
}

export function ExpandableContactsTable({ children }: { children: ReactNode }) {
  const [expanded, setExpanded] = useState(false);
  const dialog = useRef<HTMLDialogElement>(null);
  const container = useRef<HTMLDivElement>(null);
  const restoreFocus = useRef(false);
  const animation = useRef<Animation | null>(null);
  const closing = useRef(false);
  const router = useRouter();

  async function close(afterClose?: () => void) {
    const element = dialog.current;
    if (!element?.open || closing.current) return;
    closing.current = true;
    const style = getComputedStyle(element);
    const from = { opacity: style.opacity, transform: style.transform };
    animation.current?.cancel();
    element.dataset.phase = "closing";
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const exit = element.animate(
        [from, { opacity: 0, transform: "scale(0.98)" }],
        { duration: 200, easing: "ease-out", fill: "forwards" },
      );
      animation.current = exit;
      try {
        await exit.finished;
      } catch {
        // Unmounting or another lifecycle cleanup cancels the animation.
        return;
      }
    }
    element.close();
    afterClose?.();
  }

  useEffect(() => {
    if (!expanded) {
      if (restoreFocus.current) {
        restoreFocus.current = false;
        container.current
          ?.querySelector<HTMLButtonElement>(
            'button[aria-label="Expand contacts table"]',
          )
          ?.focus();
      }
      return;
    }
    const element = dialog.current;
    if (!element) return;
    closing.current = false;
    element.dataset.phase = "opening";
    if (!element.open) element.showModal();
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      animation.current = element.animate(
        [
          { opacity: 0, transform: "scale(0.98)" },
          { opacity: 1, transform: "scale(1)" },
        ],
        { duration: 200, easing: "ease-out" },
      );
    }
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      animation.current?.cancel();
      animation.current = null;
      closing.current = false;
      document.body.style.overflow = previousOverflow;
    };
  }, [expanded]);

  return (
    <ExpansionContext.Provider
      value={{
        expanded,
        expand: () => setExpanded(true),
      }}
    >
      <div ref={container} className="min-w-0">
        {!expanded && children}
        <dialog
          ref={dialog}
          className="contacts-expanded-dialog w-[calc(100vw_-_32px)] max-w-none h-[calc(100dvh_-_32px)] max-h-none overflow-hidden p-5 [&[open]]:flex [&[open]]:flex-col"
          aria-label="Expanded contacts table"
          onCancel={(event) => {
            event.preventDefault();
            void close();
          }}
          onClose={() => {
            restoreFocus.current = true;
            setExpanded(false);
          }}
        >
          <div className="mb-4 flex shrink-0 items-center justify-between gap-4">
            <h2 className="text-xl font-semibold">Contacts</h2>
            <Button
              type="button"
              variant="outline"
              title="Collapse contacts table"
              aria-label="Collapse contacts table"
              onClick={() => void close()}
            >
              <Minimize2 aria-hidden="true" />
              <span>Collapse</span>
            </Button>
          </div>
          <div
            className="min-h-0 min-w-0 flex-1 overflow-auto"
            onClickCapture={(event) => {
              const link = (event.target as Element).closest("a");
              if (
                !link ||
                event.button !== 0 ||
                event.metaKey ||
                event.ctrlKey ||
                event.shiftKey ||
                event.altKey ||
                link.hasAttribute("download") ||
                (link.target && link.target !== "_self") ||
                link.origin !== window.location.origin
              )
                return;
              // Finish the dismissal before navigating to edit or another page.
              event.preventDefault();
              void close(() => router.push(link.href));
            }}
          >
            {expanded && children}
          </div>
        </dialog>
      </div>
    </ExpansionContext.Provider>
  );
}
